class Dependant {
  constructor(
    id,
    first_name,
    last_name,
    names,
    gender,
    date_of_birth,
    age,
    user,
    user_title,
    user_phone,
    image
  ) {
    this.id = id;
    this.first_name = first_name;
    this.last_name = last_name;
    this.names = names;
    this.gender = gender;
    this.date_of_birth = date_of_birth;
    this.age = age;
    this.user = user;
    this.user_title = user_title;
    this.user_phone = user_phone;
    this.image = image;
  }
}

export default Dependant;
